<h3>Address</h3><div class="grid2"><label>Address Line 1<input name="address_line1" required></label><label>Address Line 2<input name="address_line2"></label><label>PIN Code<input name="pincode" maxlength="6" inputmode="numeric" data-pincode required><small class="hint" data-pin-status>Enter 6-digit PIN to auto-fill city/state</small></label><label>City<input name="city" required></label><label>State<input name="state" required></label><label>Country<input name="country" value="India" readonly></label></div>